-- Additive, idempotent scratch objects for write/transaction tests (PostgreSQL).
-- Run as the fixture operator in a database named cuadb_fixture_* ONLY. Tests insert
-- and delete only rows they created themselves; nothing here drops or truncates.
DO $guard$
BEGIN
  IF pg_catalog.current_database() !~ '^cuadb_fixture_' THEN
    RAISE EXCEPTION 'Refusing fixture setup outside cuadb_fixture_* database';
  END IF;
END
$guard$;
CREATE SCHEMA IF NOT EXISTS cuadb_rw_scratch;
CREATE TABLE IF NOT EXISTS cuadb_rw_scratch.items (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL UNIQUE,
  qty integer,
  note text,
  total integer GENERATED ALWAYS AS (qty * 2) STORED
);
CREATE TABLE IF NOT EXISTS cuadb_rw_scratch.audit_probe (id serial PRIMARY KEY, at timestamptz DEFAULT now());
-- A function with a side effect, to prove read statements run in read-only transactions.
CREATE OR REPLACE FUNCTION cuadb_rw_scratch.sneaky() RETURNS integer LANGUAGE sql AS
  $$ INSERT INTO cuadb_rw_scratch.audit_probe DEFAULT VALUES RETURNING id $$;
-- GRANT USAGE ON SCHEMA cuadb_rw_scratch TO <reader role>;
-- GRANT SELECT ON ALL TABLES IN SCHEMA cuadb_rw_scratch TO <reader role>; (run by the owner)
